+// Sales from the till: each sold dish uses `qty` portions of its recipe.
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** True when a ticket was already imported. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Records one sold line and consumes its ingredients (ref `sale:<ticket>`); throws not_enough_stock. */
+export function recordSale(store, { ticket, soldAt, dishId, qty }) {
+  const dish = getDish(store, dishId);
+  const recipe = getRecipe(store, dish.recipeId);
+  for (const n of scaled(recipe, qty))
+    consume(store, n.itemId, n.qty, { at: soldAt, ref: `sale:${ticket}` });
+  const sale = { id: store.nextId("sale"), ticket, soldAt, dishId, qty };
+  store.data.sales.push(sale);
+  return sale;
+}
+
+/** Per item between two days (inclusive): theoretical use from sales, actual use from consume movements, and their difference (actual - theoretical). */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  const lines = new Map();
+  const line = (itemId) => {
+    if (!lines.has(itemId)) lines.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    return lines.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    const dish = store.data.dishes?.find((d) => d.id === s.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) line(n.itemId).theoretical += n.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) line(batch.itemId).actual += m.qty;
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...lines.values()]
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId)
+    .map((l) => ({
+      itemId: l.itemId,
+      theoretical: r3(l.theoretical),
+      actual: r3(l.actual),
+      difference: r3(l.actual - l.theoretical),
+    }));
+}
